import os
import sys

sys.path.insert(0, os.getcwd())
try:
    from fizzbuzz import fizzbuzz
except Exception as e:
    sys.exit(f"fizzbuzz.py could not be imported: {e}")

def expected(i):
    fizz = i % 3 == 0 or "3" in str(i)
    buzz = i % 5 == 0 or "5" in str(i)
    return "FizzBuzz" if fizz and buzz else "Fizz" if fizz else "Buzz" if buzz else str(i)

got = fizzbuzz(100)
if not isinstance(got, list) or len(got) != 100:
    sys.exit("fizzbuzz(100) is not a list of 100 strings")
for i, value in enumerate(got, start=1):
    if value != expected(i):
        sys.exit(f"fizzbuzz(100)[{i - 1}], for {i}, is {value!r}, not {expected(i)!r}")

